    24→  if (minutes < 60) return `${minutes} Min`;
    25→  const hours = Math.floor(minutes / 60);
    26→  const mins = minutes % 60;
    27→  return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
    28→}
