    35→// Calculate streak (consecutive days with at least one completed habit)
    36→function calculateStreak(entries: TaeglicheEintraege[]): number {
    37→  const completedDates = new Set<string>();
    38→  entries.forEach(entry => {
    39→    if (entry.fields.ausgefuehrt && entry.fields.datum) {
    40→      completedDates.add(entry.fields.datum.split('T')[0]);
    41→    }
    42→  });
    43→
    44→  let streak = 0;
    45→  let currentDate = new Date();
    46→
    47→  // Check if today has entries, if not start from yesterday
    48→  const todayStr = format(currentDate, 'yyyy-MM-dd');
    49→  if (!completedDates.has(todayStr)) {
    50→    currentDate = addDays(currentDate, -1);
    51→  }
    52→
    53→  while (true) {
    54→    const dateStr = format(currentDate, 'yyyy-MM-dd');
    55→    if (completedDates.has(dateStr)) {
    56→      streak++;
    57→      currentDate = addDays(currentDate, -1);
    58→    } else {
    59→      break;
    60→    }
    61→  }
    62→
    63→  return streak;
    64→}
    65→
    66→// Get week data for chart
    67→function getWeekData(entries: TaeglicheEintraege[], habits: GewohnheitenVerwaltung[]): Array<{ day: string; dayFull: string; completion: number; date: string }> {
    68→  const weekStart = startOfWeek(new Date(), { weekStartsOn: 1 }); // Start on Monday
    69→  const totalHabits = habits.length || 1; // Avoid division by zero
    70→
    71→  return Array.from({ length: 7 }, (_, i) => {
