   166→// Circular progress ring component
   167→function CircularProgress({ percentage, size = 200 }: { percentage: number; size?: number }) {
   168→  const strokeWidth = 12;
   169→  const radius = (size - strokeWidth) / 2;
   170→  const circumference = radius * 2 * Math.PI;
   171→  const offset = circumference - (percentage / 100) * circumference;
   172→
   173→  return (
   174→    <div className="relative" style={{ width: size, height: size }}>
   175→      <svg width={size} height={size} className="transform -rotate-90">
   176→        {/* Background circle */}
   177→        <circle
   178→          cx={size / 2}
   179→          cy={size / 2}
   180→          r={radius}
   181→          fill="none"
   182→          stroke="hsl(var(--muted))"
   183→          strokeWidth={strokeWidth}
   184→        />
   185→        {/* Progress circle */}
   186→        <circle
   187→          cx={size / 2}
   188→          cy={size / 2}
   189→          r={radius}
   190→          fill="none"
   191→          stroke="hsl(var(--primary))"
   192→          strokeWidth={strokeWidth}
   193→          strokeLinecap="round"
   194→          strokeDasharray={circumference}
   195→          strokeDashoffset={offset}
   196→          className="transition-all duration-1000 ease-out"
   197→          style={{
   198→            filter: percentage === 100 ? 'drop-shadow(0 0 8px hsl(152 35% 45% / 0.5))' : 'none',
   199→          }}
   200→        />
   201→      </svg>
   202→      {/* Inner content */}
   203→      <div className="absolute inset-0 flex flex-col items-center justify-center">
   204→        <span className="text-5xl font-light text-foreground">{percentage}%</span>
   205→        <span className="text-sm text-muted-foreground">Heute erledigt</span>
   206→      </div>
   207→    </div>
   208→  );
   209→}
