   328→// Habit Card component for the list
   329→function HabitCard({
   330→  habit,
   331→  entries,
   332→  onToggleToday,
   333→}: {
   334→  habit: GewohnheitenVerwaltung;
   335→  entries: TaeglicheEintraege[];
   336→  onToggleToday: (habitId: string, currentStatus: boolean, entryId?: string) => void;
   337→}) {
   338→  const todayStr = getTodayDate();
   339→
   340→  // Check if completed today
   341→  const todayEntry = entries.find(entry => {
   342→    const habitId = extractRecordId(entry.fields.gewohnheit);
   343→    const entryDate = entry.fields.datum?.split('T')[0];
   344→    return habitId === habit.record_id && entryDate === todayStr && entry.fields.ausgefuehrt;
   345→  });
   346→  const isCompletedToday = !!todayEntry;
   347→
   348→  // Calculate weekly completion
   349→  const weekStart = startOfWeek(new Date(), { weekStartsOn: 1 });
   350→  const weekEntries = entries.filter(entry => {
   351→    const habitId = extractRecordId(entry.fields.gewohnheit);
   352→    if (habitId !== habit.record_id) return false;
   353→    const entryDate = entry.fields.datum ? parseISO(entry.fields.datum.split('T')[0]) : null;
   354→    if (!entryDate) return false;
   355→    return entryDate >= weekStart && entry.fields.ausgefuehrt;
   356→  });
   357→  const weeklyCompletion = Math.round((weekEntries.length / 7) * 100);
   358→
   359→  return (
   360→    <div
   361→      className="p-4 bg-card rounded-lg border border-border hover:shadow-md transition-shadow cursor-pointer"
   362→      onClick={() => onToggleToday(habit.record_id, isCompletedToday, todayEntry?.record_id)}
   363→    >
   364→      <div className="flex items-center justify-between mb-2">
   365→        <div className="flex-1 min-w-0">
   366→          <h3 className="font-medium text-foreground truncate">{habit.fields.gewohnheit_name}</h3>
   367→          <p className="text-sm text-muted-foreground">
   368→            Ziel: {habit.fields.zielzeit_minuten || 0} Min/Tag
   369→          </p>
   370→        </div>
   371→        <div
   372→          className={`w-8 h-8 rounded-full flex items-center justify-center transition-colors ${
   373→            isCompletedToday
   374→              ? 'bg-primary text-primary-foreground'
   375→              : 'bg-muted text-muted-foreground'
   376→          }`}
   377→        >
   378→          <Check className="w-5 h-5" />
   379→        </div>
   380→      </div>
   381→      <Progress value={weeklyCompletion} className="h-2" />
   382→      <p className="text-xs text-muted-foreground mt-1">{weeklyCompletion}% diese Woche</p>
   383→    </div>
   384→  );
   385→}
