   194→function YearGrid({ data, habits }: { data: Array<{ date: string; completion: number; count: number }>; habits: GewohnheitenVerwaltung[] }) {
   195→  // Group by weeks for the grid
   196→  const weeks: Array<Array<{ date: string; completion: number; count: number } | null>> = [];
   197→  let currentWeek: Array<{ date: string; completion: number; count: number } | null> = [];
   198→
   199→  // Pad the beginning of the year to align with weekdays
   200→  const firstDay = data[0] ? parseISO(data[0].date) : new Date();
   201→  const firstDayOfWeek = firstDay.getDay(); // 0 = Sunday
   202→  for (let i = 0; i < firstDayOfWeek; i++) {
   203→    currentWeek.push(null);
   204→  }
   205→
   206→  data.forEach((day, index) => {
   207→    currentWeek.push(day);
   208→    if (currentWeek.length === 7) {
   209→      weeks.push(currentWeek);
   210→      currentWeek = [];
   211→    }
   212→  });
   213→
   214→  // Pad the last week
   215→  while (currentWeek.length > 0 && currentWeek.length < 7) {
   216→    currentWeek.push(null);
   217→  }
   218→  if (currentWeek.length > 0) {
   219→    weeks.push(currentWeek);
   220→  }
   221→
   222→  const getColor = (completion: number) => {
   223→    if (completion === 0) return 'bg-muted';
   224→    if (completion < 25) return 'bg-primary/20';
   225→    if (completion < 50) return 'bg-primary/40';
   226→    if (completion < 75) return 'bg-primary/60';
   227→    if (completion < 100) return 'bg-primary/80';
   228→    return 'bg-primary';
   229→  };
   230→
   231→  const months = ['Jan', 'Feb', 'Mär', 'Apr', 'Mai', 'Jun', 'Jul', 'Aug', 'Sep', 'Okt', 'Nov', 'Dez'];
   232→  const today = new Date();
   233→  const currentMonth = today.getMonth();
   234→
   235→  return (
   236→    <div className="overflow-x-auto pb-2">
   237→      {/* Month labels */}
   238→      <div className="flex mb-1 text-xs text-muted-foreground">
   239→        <div className="w-6" /> {/* Spacer for day labels */}
   240→        {months.slice(0, currentMonth + 1).map((month, i) => (
   241→          <div key={month} className="flex-1 min-w-0 text-center">{month}</div>
   242→        ))}
   243→      </div>
   244→      <div className="flex gap-0.5">
   245→        {/* Day labels */}
   246→        <div className="flex flex-col gap-0.5 text-xs text-muted-foreground pr-1">
   247→          <span className="h-3 leading-3"></span>
   248→          <span className="h-3 leading-3">Mo</span>
   249→          <span className="h-3 leading-3"></span>
   250→          <span className="h-3 leading-3">Mi</span>
   251→          <span className="h-3 leading-3"></span>
   252→          <span className="h-3 leading-3">Fr</span>
   253→          <span className="h-3 leading-3"></span>
   254→        </div>
   255→        {/* Grid */}
   256→        <div className="flex gap-0.5">
   257→          {weeks.map((week, weekIndex) => (
   258→            <div key={weekIndex} className="flex flex-col gap-0.5">
   259→              {week.map((day, dayIndex) => (
   260→                <TooltipProvider key={dayIndex} delayDuration={100}>
   261→                  <Tooltip>
   262→                    <TooltipTrigger asChild>
   263→                      <div
   264→                        className={`w-3 h-3 rounded-sm transition-colors ${
   265→                          day ? getColor(day.completion) : 'bg-transparent'
   266→                        }`}
   267→                      />
   268→                    </TooltipTrigger>
   269→                    {day && (
   270→                      <TooltipContent side="top" className="text-xs">
   271→                        <p className="font-medium">{format(parseISO(day.date), 'd. MMMM yyyy', { locale: de })}</p>
   272→                        <p className="text-muted-foreground">{day.count} von {habits.length} erledigt ({day.completion}%)</p>
   273→                      </TooltipContent>
   274→                    )}
   275→                  </Tooltip>
   276→                </TooltipProvider>
   277→              ))}
   278→            </div>
   279→          ))}
   280→        </div>
   281→      </div>
   282→      {/* Legend */}
   283→      <div className="flex items-center gap-2 mt-3 text-xs text-muted-foreground justify-end">
   284→        <span>Weniger</span>
   285→        <div className="flex gap-0.5">
   286→          <div className="w-3 h-3 rounded-sm bg-muted" />
   287→          <div className="w-3 h-3 rounded-sm bg-primary/20" />
   288→          <div className="w-3 h-3 rounded-sm bg-primary/40" />
   289→          <div className="w-3 h-3 rounded-sm bg-primary/60" />
   290→          <div className="w-3 h-3 rounded-sm bg-primary/80" />
   291→          <div className="w-3 h-3 rounded-sm bg-primary" />
   292→        </div>
   293→        <span>Mehr</span>
   294→      </div>
   295→    </div>
   296→  );
   297→}
