   422→  habit: GewohnheitenVerwaltung;
   423→  entries: TaeglicheEintraege[];
   424→  onToggleToday: (habitId: string, currentStatus: boolean, entryId?: string) => void;
   425→}) {
   426→  const todayStr = getTodayDate();
   427→
   428→  // Check if completed today
   429→  const todayEntry = entries.find(entry => {
   430→    const habitId = extractRecordId(entry.fields.gewohnheit);
   431→    const entryDate = entry.fields.datum?.split('T')[0];
   432→    return habitId === habit.record_id && entryDate === todayStr && entry.fields.ausgefuehrt;
   433→  });
   434→  const isCompletedToday = !!todayEntry;
   435→
   436→  // Calculate overall consistency for this habit
   437→  const habitEntries = entries.filter(entry => {
   438→    const habitId = extractRecordId(entry.fields.gewohnheit);
   439→    return habitId === habit.record_id && entry.fields.ausgefuehrt;
