   441→  const uniqueDays = new Set(habitEntries.map(e => e.fields.datum?.split('T')[0])).size;
   442→  const daysSinceStart = getDayOfYear(new Date());
   443→  const consistencyRate = Math.round((uniqueDays / daysSinceStart) * 100);
   444→
   445→  // Calculate streak for this habit
   446→  const habitStreak = calculateStreak(entries.filter(entry => {
