    25→// Format minutes to hours and minutes in a beautiful way
    26→function formatTimeInvested(minutes: number): { hours: number; mins: number; display: string; shortDisplay: string } {
    27→  const hours = Math.floor(minutes / 60);
    28→  const mins = minutes % 60;
    29→
