    39→// Calculate time invested per habit
    40→function calculateTimePerHabit(entries: TaeglicheEintraege[], habits: GewohnheitenVerwaltung[]): Map<string, number> {
    41→  const timeMap = new Map<string, number>();
    42→
    43→  // Initialize all habits with 0
    44→  habits.forEach(habit => {
    45→    timeMap.set(habit.record_id, 0);
