    50→    if (entry.fields.ausgefuehrt && entry.fields.investierte_zeit_minuten) {
    51→      const habitId = extractRecordId(entry.fields.gewohnheit);
    52→      if (habitId) {
    53→        const current = timeMap.get(habitId) || 0;
