    62→// Calculate streak (consecutive days with at least one completed habit)
    63→function calculateStreak(entries: TaeglicheEintraege[]): number {
    64→  const completedDates = new Set<string>();
    65→  entries.forEach(entry => {
    66→    if (entry.fields.ausgefuehrt && entry.fields.datum) {
    67→      completedDates.add(entry.fields.datum.split('T')[0]);
    68→    }
    69→  });
    70→
    71→  let streak = 0;
    72→  let currentDate = new Date();
    73→
    74→  const todayStr = format(currentDate, 'yyyy-MM-dd');
    75→  if (!completedDates.has(todayStr)) {
    76→    currentDate = addDays(currentDate, -1);
    77→  }
    78→
    79→  while (true) {
    80→    const dateStr = format(currentDate, 'yyyy-MM-dd');
    81→    if (completedDates.has(dateStr)) {
    82→      streak++;
    83→      currentDate = addDays(currentDate, -1);
    84→    } else {
    85→      break;
    86→    }
    87→  }
    88→
    89→  return streak;
    90→}
    91→
    92→// Calculate longest streak ever
    93→function calculateLongestStreak(entries: TaeglicheEintraege[]): number {
    94→  const completedDates = new Set<string>();
    95→  entries.forEach(entry => {
    96→    if (entry.fields.ausgefuehrt && entry.fields.datum) {
    97→      completedDates.add(entry.fields.datum.split('T')[0]);
    98→    }
    99→  });
   100→
   101→  if (completedDates.size === 0) return 0;
   102→
   103→  const sortedDates = Array.from(completedDates).sort();
   104→  let longestStreak = 1;
   105→  let currentStreak = 1;
   106→
   107→  for (let i = 1; i < sortedDates.length; i++) {
   108→    const prevDate = parseISO(sortedDates[i - 1]);
   109→    const currDate = parseISO(sortedDates[i]);
   110→    const diff = differenceInDays(currDate, prevDate);
   111→
   112→    if (diff === 1) {
   113→      currentStreak++;
   114→      longestStreak = Math.max(longestStreak, currentStreak);
   115→    } else {
   116→      currentStreak = 1;
   117→    }
   118→  }
   119→
   120→  return longestStreak;
   121→}
