   123→// Calculate FULL year overview data (including future days)
   124→function getFullYearData(entries: TaeglicheEintraege[], habits: GewohnheitenVerwaltung[]): Array<{ date: string; completion: number; count: number; isFuture: boolean; isToday: boolean }> {
   125→  const today = new Date();
   126→  const yearStart = startOfYear(today);
   127→  const yearEnd = endOfYear(today);
   128→  const totalHabits = habits.length || 1;
   129→
   130→  // Create map of completions per day
   131→  const completionMap = new Map<string, number>();
   132→  entries.forEach(entry => {
   133→    if (entry.fields.ausgefuehrt && entry.fields.datum) {
   134→      const dateStr = entry.fields.datum.split('T')[0];
   135→      completionMap.set(dateStr, (completionMap.get(dateStr) || 0) + 1);
   136→    }
   137→  });
   138→
   139→  // Generate data for ENTIRE year
   140→  const days = eachDayOfInterval({ start: yearStart, end: yearEnd });
   141→  return days.map(date => {
   142→    const dateStr = format(date, 'yyyy-MM-dd');
   143→    const count = completionMap.get(dateStr) || 0;
   144→    const completion = Math.min(Math.round((count / totalHabits) * 100), 100);
   145→    const isFuture = isAfter(date, today);
   146→    const isToday = isDateToday(date);
   147→    return { date: dateStr, completion, count, isFuture, isToday };
   148→  });
   149→}
