   157→    }
   158→  });
   159→
   160→  const totalDays = getDayOfYear(new Date());
   161→  const activeDays = completedDates.size;
   162→  const rate = Math.round((activeDays / totalDays) * 100);
   163→
   164→  return { rate, activeDays, totalDays };
   165→}
