   751→// Desktop Habit Card
   752→function HabitCard({
   753→  habit,
   754→  entries,
   755→  onToggleToday,
   756→}: {
   757→  habit: GewohnheitenVerwaltung;
   758→  entries: TaeglicheEintraege[];
   759→  onToggleToday: (habitId: string, currentStatus: boolean, entryId?: string) => void;
   760→}) {
   761→  const todayStr = getTodayDate();
   762→
   763→  const todayEntry = entries.find(entry => {
   764→    const habitId = extractRecordId(entry.fields.gewohnheit);
   765→    const entryDate = entry.fields.datum?.split('T')[0];
   766→    return habitId === habit.record_id && entryDate === todayStr && entry.fields.ausgefuehrt;
   767→  });
   768→  const isCompletedToday = !!todayEntry;
   769→
   770→  const habitEntries = entries.filter(entry => {
   771→    const habitId = extractRecordId(entry.fields.gewohnheit);
   772→    return habitId === habit.record_id && entry.fields.ausgefuehrt;
   773→  });
   774→  const uniqueDays = new Set(habitEntries.map(e => e.fields.datum?.split('T')[0])).size;
   775→  const daysSinceStart = getDayOfYear(new Date());
   776→  const consistencyRate = Math.round((uniqueDays / daysSinceStart) * 100);
   777→
   778→  const habitStreak = calculateStreak(entries.filter(entry => {
   779→    const habitId = extractRecordId(entry.fields.gewohnheit);
   780→    return habitId === habit.record_id;
   781→  }));
   782→
   783→  return (
   784→    <Card
   785→      className="hover:border-primary/50 transition-colors cursor-pointer"
   786→      onClick={() => onToggleToday(habit.record_id, isCompletedToday, todayEntry?.record_id)}
