   794→                {habit.fields.beschreibung}
   795→              </p>
   796→            )}
   797→          </div>
   798→          <div
   799→            className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${
   800→              isCompletedToday
   801→                ? 'bg-primary text-primary-foreground'
   802→                : 'bg-muted text-muted-foreground'
   803→            }`}
   804→          >
   805→            <Check className="w-5 h-5" />
   806→          </div>
