}

// Time Invested Bar Component - Shows time with animated progress bar
function TimeInvestedBar({
  habitName,
  minutes,
  maxMinutes,
  color,
}: {
  habitName: string;
  minutes: number;
  maxMinutes: number;
  color: string;
}) {
