}

// Mobile Time Invested Row
function MobileTimeRow({
  habitName,
  minutes,
  maxMinutes,
}: {
  habitName: string;
  minutes: number;
  maxMinutes: number;
}) {
  const { shortDisplay } = formatTimeInvested(minutes);
  const percentage = maxMinutes > 0 ? Math.min((minutes / maxMinutes) * 100, 100) : 0;

  return (
