        </div>

        {/* Fixed Bottom Action Button */}
        <div className="fixed bottom-0 left-0 right-0 p-3 bg-background/95 backdrop-blur border-t border-border">
          <Button
            className="w-full h-11 text-sm gap-2"
            onClick={() => setDialogOpen(true)}
